{
  "findings": [
    {
      "check_id": "CKV_AWS_8",
      "title": "EC2 root volume encryption not enabled",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "HIGH",
      "explanation": "The instance does not explicitly encrypt its root EBS volume, which could leave data at rest unencrypted when account-level EBS encryption is not enabled."
    },
    {
      "check_id": "CKV_AWS_79",
      "title": "EC2 instance does not require IMDSv2",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "HIGH",
      "explanation": "No metadata options are configured, so the instance can permit IMDSv1, increasing the risk of credential theft through server-side request forgery."
    },
    {
      "check_id": "CKV_AWS_126",
      "title": "EC2 detailed monitoring is disabled",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "LOW",
      "explanation": "The instance does not enable detailed CloudWatch monitoring, reducing the granularity available for security monitoring and incident investigation."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"MyFirstInstnace\" {\n  ami                         = lookup(var.AMIS, var.AWS_REGION)\n  instance_type               = \"t2.micro\"\n  availability_zone           = \"us-east-2a\"\n  key_name                    = aws_key_pair.levelup_key.key_name\n  vpc_security_group_ids      = [aws_security_group.allow-levelup-ssh.id]\n  subnet_id                   = aws_subnet.levelupvpc-public-1.id\n  monitoring                  = true\n\n  root_block_device {\n    encrypted = true\n  }\n\n  metadata_options {\n    http_endpoint = \"enabled\"\n    http_tokens   = \"required\"\n  }\n}\n",
  "fix_summary": "Enabled encryption for the instance root EBS volume, required IMDSv2 for metadata access, and enabled detailed CloudWatch monitoring."
}
